package com.mydrops;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/** Correlates a local Drop intent, inventory loss and a confirmed ground change. */
final class DropTracker
{
    static final int WINDOW = 3, MAX_PENDING = 28, MAX_TRACKED = 256;
    private final Map<Integer, Intent> pending = new HashMap<>();
    private final Map<TileItem, Tile> tracked = new IdentityHashMap<>();

    void intent(int id, int count, int quantity, int tick, WorldView view, WorldPoint location)
    {
        if (count <= 0 || (pending.size() >= MAX_PENDING && !pending.containsKey(id))) { return; }
        Intent intent = pending.get(id);
        if (intent == null || tick > intent.expires || intent.view != view || !intent.location.equals(location))
        {
            intent = new Intent(count, view, location);
            intent.expires = tick + WINDOW;
            pending.put(id, intent);
        }
        intent.requested = Math.min((long) intent.before, intent.requested + quantity);
    }

    void ground(TileItem item, Tile tile, int added, int tick, WorldPoint playerLocation)
    {
        Intent intent = pending.get(item.getId());
        if (intent == null || tick > intent.expires || added <= 0
            || item.getOwnership() != TileItem.OWNERSHIP_SELF || tile.getItemLayer() == null
            || tile.getItemLayer().getWorldView() != intent.view
            || (!tile.getWorldLocation().equals(intent.location) && !tile.getWorldLocation().equals(playerLocation)))
        {
            return;
        }
        if (intent.candidates.size() < MAX_PENDING)
        {
            intent.candidates.add(new Candidate(item, tile, added));
        }
        else { pending.remove(item.getId()); }
    }

    void confirm(int tick, ToIntFunction<Integer> inventoryCount)
    {
        Iterator<Map.Entry<Integer, Intent>> iterator = pending.entrySet().iterator();
        while (iterator.hasNext())
        {
            Map.Entry<Integer, Intent> entry = iterator.next();
            Intent intent = entry.getValue();
            // Expired intents cannot be revived by an unrelated later inventory reduction.
            if (tick > intent.expires) { iterator.remove(); continue; }
            int lost = Math.max(0, intent.before - inventoryCount.applyAsInt(entry.getKey()));
            long observed = 0;
            for (Candidate candidate : intent.candidates) { observed += candidate.added; }
            // Fail closed when simultaneous loot could be mistaken for the dropped item.
            if (lost <= 0) { continue; }
            if (observed == lost && lost <= intent.requested)
            {
                for (Candidate candidate : intent.candidates)
                {
                    if (tracked.size() < MAX_TRACKED || tracked.containsKey(candidate.item))
                    {
                        tracked.put(candidate.item, candidate.tile);
                    }
                }
            }
            // A successful or ambiguous inventory change finishes this short-lived correlation.
            iterator.remove();
        }
    }

    Map<TileItem, Tile> tracked() { return tracked; }
    void restore(TileItem item, Tile tile)
    {
        if (tracked.size() < MAX_TRACKED) { tracked.put(item, tile); }
    }
    void cancel(int id) { pending.remove(id); }

    void remove(TileItem item)
    {
        tracked.remove(item);
        for (Intent intent : pending.values()) { intent.candidates.removeIf(c -> c.item == item); }
    }

    void unload(WorldView view)
    {
        tracked.values().removeIf(tile -> tile.getItemLayer() == null || tile.getItemLayer().getWorldView() == view);
        pending.values().removeIf(intent -> intent.view == view);
    }

    void clear() { pending.clear(); tracked.clear(); }

    private static final class Intent
    {
        int before, expires;
        long requested;
        final WorldView view;
        final WorldPoint location;
        final List<Candidate> candidates = new ArrayList<>();
        Intent(int before, WorldView view, WorldPoint location)
        {
            this.before = before; this.view = view; this.location = location;
        }
    }

    private static final class Candidate
    {
        final TileItem item;
        final Tile tile;
        final int added;
        Candidate(TileItem item, Tile tile, int added) { this.item = item; this.tile = tile; this.added = added; }
    }
}

package com.mydrops;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup(MyDropsConfig.GROUP)
public interface MyDropsConfig extends Config
{
    String GROUP = "mydrops";

    @ConfigSection(name = "Item filter", description = "Which own drops and optional GIM group items to mark", position = 0)
    String FILTER = "filter";
    @ConfigSection(name = "Appearance", description = "Colors include an opacity slider", position = 1)
    String APPEARANCE = "appearance";

    @ConfigItem(keyName = "resourcesOnly", name = "Resources only", description = "Apply the categories and extra items below to own drops and enabled GIM group items. Off: include all item types.", section = FILTER, position = 0)
    default boolean resourcesOnly() { return true; }

    @ConfigItem(keyName = "food", name = "Food", description = "Items with an Eat action", section = FILTER, position = 1)
    default boolean food() { return true; }

    @ConfigItem(keyName = "potions", name = "Potions and drinks", description = "Items with a Drink action", section = FILTER, position = 2)
    default boolean potions() { return true; }

    @ConfigItem(keyName = "ammunition", name = "Ammunition", description = "Common arrows, bolts, darts, knives, javelins, chinchompas and cannonballs; add exceptions below", section = FILTER, position = 3)
    default boolean ammunition() { return true; }

    @ConfigItem(keyName = "runes", name = "Runes", description = "Items named rune or runes, including combination runes", section = FILTER, position = 4)
    default boolean runes() { return true; }

    @ConfigItem(keyName = "extraItems", name = "Extra items", description = "Comma-separated exact item names to add in resource mode. No wildcards. Noted items use their unnoted name.", section = FILTER, position = 5)
    default String extraItems() { return ""; }

    @ConfigItem(keyName = "groupItems", name = "Highlight GIM group items", description = "Also mark group-owned ground items, including loot, using the same resource filters. No Party setup or dropper names.", section = FILTER, position = 6)
    default boolean groupItems() { return false; }

    @Alpha
    @ConfigItem(keyName = "groupColor", name = "GIM group color", description = "Color and opacity for group outlines and names. Tile fill also uses Tile fill color opacity. Text background stays shared. Zero opacity hides all group marks.", section = FILTER, position = 7)
    default Color groupColor() { return Color.MAGENTA; }

    @ConfigItem(keyName = "outline", name = "Item outline", description = "Outline the individual matching item", section = APPEARANCE, position = 0)
    default boolean outline() { return true; }

    @Alpha
    @ConfigItem(keyName = "outlineColor", name = "Outline color", description = "Outline color and opacity", section = APPEARANCE, position = 1)
    default Color outlineColor() { return Color.CYAN; }

    @Range(min = 1, max = 5)
    @ConfigItem(keyName = "outlineWidth", name = "Outline width", description = "Outline width in pixels", section = APPEARANCE, position = 2)
    default int outlineWidth() { return 2; }

    @ConfigItem(keyName = "tileFill", name = "Ground tile fill", description = "Fill the ground tile beneath matching items; this colors the tile, not the item model", section = APPEARANCE, position = 3)
    default boolean tileFill() { return false; }

    @Alpha
    @ConfigItem(keyName = "fillColor", name = "Tile fill color", description = "Ground tile color and opacity", section = APPEARANCE, position = 4)
    default Color fillColor() { return new Color(0, 255, 255, 45); }

    @ConfigItem(keyName = "text", name = "Show item names", description = "Show separate labels. Ground Items may also draw labels; use outlines only to avoid duplicates.", section = APPEARANCE, position = 5)
    default boolean text() { return false; }

    @Alpha
    @ConfigItem(keyName = "textColor", name = "Text color", description = "Item-name color and opacity", section = APPEARANCE, position = 6)
    default Color textColor() { return Color.CYAN; }

    @Alpha
    @ConfigItem(keyName = "backgroundColor", name = "Text background", description = "Label background color and opacity; zero opacity hides the background", section = APPEARANCE, position = 7)
    default Color backgroundColor() { return new Color(0, 0, 0, 150); }
}

package com.mydrops;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemLayer;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

final class MyDropsOverlay extends Overlay
{
    private final Client client;
    private final MyDropsPlugin plugin;
    private final MyDropsConfig config;
    private final ModelOutlineRenderer outlines;
    private final Map<Tile, Integer> rows = new HashMap<>();

    @Inject MyDropsOverlay(Client client, MyDropsPlugin plugin, MyDropsConfig config, ModelOutlineRenderer outlines)
    {
        this.client = client; this.plugin = plugin; this.config = config; this.outlines = outlines;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null) { return null; }
        rows.clear();
        boolean outline = config.outline(), fill = config.tileFill(), text = config.text();
        if (!outline && !fill && !text) { return null; }
        Color lineColor = config.outlineColor(), fillColor = config.fillColor();
        Color textColor = config.textColor(), background = config.backgroundColor();
        Color groupColor = config.groupColor();
        boolean groupEnabled = config.groupItems();
        Color groupFill = new Color(groupColor.getRed(), groupColor.getGreen(), groupColor.getBlue(), groupColor.getAlpha() * fillColor.getAlpha() / 255);
        FontMetrics metrics = graphics.getFontMetrics();
        boolean resourcesOnly = config.resourcesOnly();
        int mask = (config.food() ? ResourceFilter.FOOD : 0) | (config.potions() ? ResourceFilter.POTIONS : 0)
            | (config.ammunition() ? ResourceFilter.AMMO : 0) | (config.runes() ? ResourceFilter.RUNES : 0);
        int width = config.outlineWidth();
        Color shadow = new Color(0, 0, 0, textColor.getAlpha());
        Color groupShadow = new Color(0, 0, 0, groupColor.getAlpha());
        // Own drops render first, so their tile fill wins on a mixed tile.
        for (int pass = 0; pass < 2; pass++)
        {
            boolean group = pass == 1;
            if (group && (!groupEnabled || groupColor.getAlpha() == 0)) { continue; }
            Color itemLine = group ? groupColor : lineColor, itemFill = group ? groupFill : fillColor;
            Color itemText = group ? groupColor : textColor, itemShadow = group ? groupShadow : shadow;
            Map<TileItem, Tile> items = group ? plugin.groupItems : plugin.tracker.tracked();
            for (Map.Entry<TileItem, Tile> entry : items.entrySet())
            {
                TileItem item = entry.getKey();
                if (group && (item.getOwnership() != TileItem.OWNERSHIP_GROUP || plugin.tracker.tracked().containsKey(item))) { continue; }
                Tile tile = entry.getValue();
                MyDropsPlugin.Label label = plugin.labels.get(item);
                if (label == null || !plugin.filter.matches(label.filterName, label.categories, resourcesOnly, mask)) { continue; }
                ItemLayer layer = tile.getItemLayer();
                if (layer == null || layer.getWorldView().getPlane() != tile.getPlane() || layer.getCanvasLocation() == null) { continue; }
                int row = rows.getOrDefault(tile, 0);
                rows.put(tile, row + 1);
                if (fill && row == 0 && itemFill.getAlpha() > 0)
                {
                    Polygon polygon = layer.getCanvasTilePoly();
                    if (polygon != null) { graphics.setColor(itemFill); graphics.fill(polygon); }
                }
                if (outline && itemLine.getAlpha() > 0) { outlines.drawOutline(layer, item, width, itemLine, 0); }
                if (text)
                {
                    Point point = layer.getCanvasTextLocation(graphics, label.text, 20);
                    if (point == null) { continue; }
                    int x = point.getX(), y = point.getY() - row * (metrics.getHeight() + 4);
                    graphics.setColor(background);
                    graphics.fillRect(x - 3, y - metrics.getAscent() - 2, metrics.stringWidth(label.text) + 6, metrics.getHeight() + 4);
                    graphics.setColor(itemShadow);
                    graphics.drawString(label.text, x + 1, y + 1);
                    graphics.setColor(itemText);
                    graphics.drawString(label.text, x, y);
                }
            }
        }
        return null;
    }
}

package com.mydrops;

import com.google.inject.Provides;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(name = "My Drops", description = "Color your deliberate drops and optional GIM group items", tags = {"ground", "supplies", "food", "potions", "ammunition", "gim"})
public class MyDropsPlugin extends Plugin
{
    @Inject Client client;
    @Inject ItemManager itemManager;
    @Inject MyDropsConfig config;
    @Inject OverlayManager overlays;
    @Inject MyDropsOverlay overlay;

    final DropTracker tracker = new DropTracker();
    final ReloadedDrops reload = new ReloadedDrops();
    final ResourceFilter filter = new ResourceFilter();
    final Map<TileItem, Label> labels = new IdentityHashMap<>();
    final Map<TileItem, Tile> groupItems = new LinkedHashMap<>();

    @Provides MyDropsConfig provideConfig(ConfigManager manager) { return manager.getConfig(MyDropsConfig.class); }

    @Override protected void startUp()
    {
        reset();
        filter.setExtras(config.extraItems());
        overlays.add(overlay);
    }

    @Override protected void shutDown() { overlays.remove(overlay); reset(); }

    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (MyDropsConfig.GROUP.equals(event.getGroup()) && "extraItems".equals(event.getKey()))
        {
            filter.setExtras(config.extraItems());
        }
    }

    @Subscribe public void onMenuOptionClicked(MenuOptionClicked event)
    {
        Player player = client.getLocalPlayer();
        if (player == null || event.isConsumed() || !event.isItemOp()
            || event.getParam1() >>> 16 != InterfaceID.INVENTORY) { return; }
        if (!"Drop".equalsIgnoreCase(Text.removeTags(event.getMenuOption())))
        {
            tracker.cancel(event.getItemId());
            return;
        }
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        Item slot = inventory == null ? null : inventory.getItem(event.getParam0());
        if (slot == null || slot.getId() != event.getItemId()) { return; }
        tracker.intent(slot.getId(), inventory.count(slot.getId()), slot.getQuantity(), client.getTickCount(), player.getWorldView(), player.getWorldLocation());
    }

    @Subscribe public void onItemSpawned(ItemSpawned event)
    {
        ground(event.getItem(), event.getTile(), event.getItem().getQuantity());
        reload.spawned(event.getItem(), event.getTile(), client.getWorld(), client.getTickCount());
    }

    @Subscribe public void onItemQuantityChanged(ItemQuantityChanged event)
    {
        reload.quantityChanged(event.getItem(), event.getTile(), event.getOldQuantity(), client.getWorld(), client.getTickCount());
        ground(event.getItem(), event.getTile(), event.getNewQuantity() - event.getOldQuantity());
        Label label = labels.get(event.getItem());
        if (label != null) { label.quantity(event.getNewQuantity()); }
    }

    private void ground(TileItem item, Tile tile, int added)
    {
        if (item.getOwnership() == TileItem.OWNERSHIP_GROUP && item.getQuantity() > 0)
        {
            if (!groupItems.containsKey(item) && groupItems.size() >= DropTracker.MAX_TRACKED)
            {
                TileItem oldest = groupItems.keySet().iterator().next();
                groupItems.remove(oldest);
                if (!tracker.tracked().containsKey(oldest)) { labels.remove(oldest); }
            }
            groupItems.put(item, tile);
            cacheLabel(item);
        }
        Player player = client.getLocalPlayer();
        if (player != null) { tracker.ground(item, tile, added, client.getTickCount(), player.getWorldLocation()); }
    }

    @Subscribe public void onItemDespawned(ItemDespawned event)
    {
        reload.despawned(event.getItem(), event.getTile(), client.getWorld(), client.getTickCount());
        tracker.remove(event.getItem());
        groupItems.remove(event.getItem());
        labels.remove(event.getItem());
    }

    @Subscribe public void onGameTick(GameTick event)
    {
        int tick = client.getTickCount();
        reload.expire(tick);
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) { return; }
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            for (ReloadedDrops.Candidate candidate : reload.finish(client.getWorld(), tick))
            {
                tracker.restore(candidate.item, candidate.tile);
            }
        }
        tracker.confirm(tick, inventory::count);
        for (TileItem item : tracker.tracked().keySet())
        {
            cacheLabel(item);
        }
    }

    private void cacheLabel(TileItem item)
    {
        if (labels.containsKey(item)) { return; }
        ItemComposition definition = itemManager.getItemComposition(item.getId());
        ItemComposition base = definition.getNote() == -1 ? definition : itemManager.getItemComposition(definition.getLinkedNoteId());
        Label label = new Label(definition.getName(), base.getName(), ResourceFilter.classify(base));
        label.quantity(item.getQuantity());
        labels.put(item, label);
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOADING)
        {
            reload.loading(tracker.tracked(), client.getWorld(), client.getTickCount());
            clearMarks();
        }
        else if (event.getGameState() != GameState.LOGGED_IN) { reset(); }
    }

    @Subscribe public void onWorldViewUnloaded(WorldViewUnloaded event)
    {
        tracker.unload(event.getWorldView());
        reload.unloaded(event.getWorldView());
        groupItems.values().removeIf(tile -> tile.getItemLayer() == null || tile.getItemLayer().getWorldView() == event.getWorldView());
        labels.keySet().removeIf(item -> !tracker.tracked().containsKey(item) && !groupItems.containsKey(item));
    }

    private void clearMarks() { tracker.clear(); groupItems.clear(); labels.clear(); }
    private void reset() { clearMarks(); reload.clear(); }

    static final class Label
    {
        final String name, filterName;
        final int categories;
        String text;
        Label(String name, String filterName, int categories) { this.name = name; this.filterName = filterName.toLowerCase(Locale.ROOT); this.categories = categories; }
        void quantity(int amount) { text = amount > 1 ? name + " (" + amount + ")" : name; }
    }
}

package com.mydrops;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.runelite.api.ItemLayer;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/** Rebinds confirmed drops to scene-reloaded items only when their full lifetime matches. */
final class ReloadedDrops
{
    private final Map<Key, Boolean> saved = new HashMap<>();
    private final Map<Key, Candidate> replayed = new HashMap<>();
    private final Set<Key> ambiguous = new HashSet<>();
    private int world = -1;
    private int nextExpiry = Integer.MAX_VALUE;
    private boolean replaying;

    void loading(Map<TileItem, Tile> confirmed, int currentWorld, int tick)
    {
        if (world != currentWorld) { clear(); world = currentWorld; }
        expire(tick);
        Set<Key> seen = new HashSet<>();
        for (Map.Entry<TileItem, Tile> entry : confirmed.entrySet())
        {
            Key key = Key.of(entry.getKey(), entry.getValue(), currentWorld, tick, entry.getKey().getQuantity());
            if (key == null) { continue; }
            if (!seen.add(key))
            {
                if (saved.containsKey(key)) { saved.put(key, false); }
            }
            else if (saved.size() < DropTracker.MAX_TRACKED)
            {
                saved.putIfAbsent(key, true);
                nextExpiry = Math.min(nextExpiry, key.despawn);
            }
        }
        replayed.clear();
        ambiguous.clear();
        replaying = true;
    }

    void spawned(TileItem item, Tile tile, int currentWorld, int tick)
    {
        if (!replaying || world != currentWorld) { return; }
        Key key = Key.of(item, tile, currentWorld, tick, item.getQuantity());
        if (key == null || !Boolean.TRUE.equals(saved.get(key))) { return; }
        if (replayed.putIfAbsent(key, new Candidate(item, tile)) != null)
        {
            ambiguous.add(key);
            saved.put(key, false);
        }
    }

    List<Candidate> finish(int currentWorld, int tick)
    {
        if (!replaying) { return Collections.emptyList(); }
        expire(tick);
        List<Candidate> matches = new ArrayList<>();
        if (world == currentWorld)
        {
            for (Map.Entry<Key, Candidate> entry : replayed.entrySet())
            {
                if (!ambiguous.contains(entry.getKey()) && Boolean.TRUE.equals(saved.get(entry.getKey())))
                {
                    Candidate candidate = entry.getValue();
                    Key current = Key.of(candidate.item, candidate.tile, currentWorld, tick, candidate.item.getQuantity());
                    if (entry.getKey().equals(current)) { matches.add(candidate); }
                    else { saved.remove(entry.getKey()); }
                }
            }
        }
        replayed.clear();
        ambiguous.clear();
        replaying = false;
        return matches;
    }

    void quantityChanged(TileItem item, Tile tile, int oldQuantity, int currentWorld, int tick)
    {
        Key old = Key.of(item, tile, currentWorld, tick, oldQuantity);
        if (old != null && (!replaying || (replayed.containsKey(old) && replayed.get(old).item == item)))
        {
            saved.remove(old); replayed.remove(old);
        }
    }

    void despawned(TileItem item, Tile tile, int currentWorld, int tick)
    {
        Key key = Key.of(item, tile, currentWorld, tick, item.getQuantity());
        if (key != null && (!replaying || (replayed.containsKey(key) && replayed.get(key).item == item)))
        {
            saved.remove(key); replayed.remove(key);
        }
        replayed.values().removeIf(candidate -> candidate.item == item);
    }

    void unloaded(WorldView view)
    {
        saved.keySet().removeIf(key -> key.view == view.getId());
        ambiguous.removeIf(key -> key.view == view.getId());
        replayed.values().removeIf(candidate -> candidate.tile.getItemLayer() == null
            || candidate.tile.getItemLayer().getWorldView() == null
            || candidate.tile.getItemLayer().getWorldView().getId() == view.getId());
    }

    void clear()
    {
        saved.clear(); replayed.clear(); ambiguous.clear(); replaying = false;
        world = -1; nextExpiry = Integer.MAX_VALUE;
    }

    int savedCount() { return saved.size(); }

    void expire(int tick)
    {
        if (tick < nextExpiry) { return; }
        saved.keySet().removeIf(key -> key.despawn <= tick);
        nextExpiry = Integer.MAX_VALUE;
        for (Key key : saved.keySet()) { nextExpiry = Math.min(nextExpiry, key.despawn); }
    }

    static final class Candidate
    {
        final TileItem item;
        final Tile tile;
        Candidate(TileItem item, Tile tile) { this.item = item; this.tile = tile; }
    }

    private static final class Key
    {
        final int world, view, id, quantity, visible, despawn;
        final WorldPoint point;

        private Key(int world, int view, int id, int quantity, int visible, int despawn, WorldPoint point)
        {
            this.world = world; this.view = view; this.id = id; this.quantity = quantity;
            this.visible = visible; this.despawn = despawn; this.point = point;
        }

        static Key of(TileItem item, Tile tile, int world, int tick, int quantity)
        {
            ItemLayer layer = tile.getItemLayer();
            if (item.getOwnership() != TileItem.OWNERSHIP_SELF || quantity <= 0 || item.getVisibleTime() <= 0
                || item.getDespawnTime() <= tick || layer == null || layer.getWorldView() == null
                || tile.getWorldLocation() == null) { return null; }
            return new Key(world, layer.getWorldView().getId(), item.getId(), quantity,
                item.getVisibleTime(), item.getDespawnTime(), tile.getWorldLocation());
        }

        @Override public boolean equals(Object other)
        {
            if (!(other instanceof Key)) { return false; }
            Key key = (Key) other;
            return world == key.world && view == key.view && id == key.id && quantity == key.quantity
                && visible == key.visible && despawn == key.despawn && point.equals(key.point);
        }

        @Override public int hashCode()
        {
            return Objects.hash(world, view, id, quantity, visible, despawn, point);
        }
    }
}

package com.mydrops;

import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.ItemComposition;

final class ResourceFilter
{
    static final int FOOD = 1, POTIONS = 2, AMMO = 4, RUNES = 8;
    private volatile Set<String> extras = new HashSet<>();

    void setExtras(String csv)
    {
        Set<String> parsed = new HashSet<>();
        for (String entry : csv.split(","))
        {
            String name = entry.trim().toLowerCase(Locale.ROOT);
            if (!name.isEmpty()) { parsed.add(name); }
        }
        extras = parsed;
    }

    boolean matches(String normalizedName, int categories, boolean resourcesOnly, int mask)
    {
        return !resourcesOnly || extras.contains(normalizedName) || (categories & mask) != 0;
    }

    static int classify(ItemComposition item)
    {
        int result = 0;
        String[] actions = item.getInventoryActions();
        if (actions != null)
        {
            for (String action : actions)
            {
                if ("Eat".equalsIgnoreCase(action)) { result |= FOOD; }
                if ("Drink".equalsIgnoreCase(action)) { result |= POTIONS; }
            }
        }
        // Name matching is a small, explicit approximation, evaluated once per confirmed drop.
        String name = item.getName().toLowerCase(Locale.ROOT).replaceAll("\\([^)]*\\)", "").trim();
        for (String ending : new String[]{"arrow", "arrows", "bolt", "bolts", "dart", "darts", "javelin", "javelins", "chinchompa", "chinchompas", "cannonball", "cannonballs"})
        {
            if (name.equals(ending) || name.endsWith(" " + ending)) { result |= AMMO; }
        }
        if (name.matches("(bronze|iron|steel|black|mithril|adamant|rune|dragon) (knife|knives)")) { result |= AMMO; }
        if (name.equals("toktz-xil-ul")) { result |= AMMO; }
        if (name.endsWith(" rune") || name.endsWith(" runes")) { result |= RUNES; }
        return result;
    }
}

package com.mydrops;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.nio.file.Files;
import java.nio.file.Path;
import javax.imageio.ImageIO;
import net.runelite.api.Client;
import net.runelite.api.ItemLayer;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Tile;
