    {
        drop(); when(item.getOwnership()).thenReturn(TileItem.OWNERSHIP_GROUP); plugin.onItemSpawned(new ItemSpawned(tile, item));
        for (int i = 0; i < DropTracker.MAX_TRACKED; i++)
